import { useState } from "react";
import { Eye, EyeOff } from 'lucide-react';
import StudentDashboard from "../StudentDashboard";
import MentorDashboard from "../MentorDashboard";
import PlacementDashboard from "../PlacementDashboard";

const ProfessionalLogin = () => {
  const [selectedUserType, setSelectedUserType] = useState('');
  const [showLogin, setShowLogin] = useState(false);
  const [showPassword, setShowPassword] = useState(false);
  const [isLoading, setIsLoading] = useState(false);
  const [loginData, setLoginData] = useState({
    email: '',
    password: ''
  });
  const [loginError, setLoginError] = useState('');
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [authenticatedUser, setAuthenticatedUser] = useState(null);

  const VALID_CREDENTIALS = {
    'student': { email: 'student@college.edu', password: 'student123' },
    'mentor': { email: 'mentor@college.edu', password: 'mentor123' },
    'placement-cell': { email: 'placement@college.edu', password: 'placement123' }
  };

  const userTypes = [
    {
      id: 'student',
      title: 'Student',
      description: 'Access placement opportunities and track applications'
    },
    {
      id: 'mentor',
      title: 'Mentor',
      description: 'Guide students and review placement applications'
    },
    {
      id: 'placement-cell',
      title: 'Placement Cell',
      description: 'Manage recruitment drives and coordinate with companies'
    }
  ];

  const handleLogin = async (e) => {
    e.preventDefault();
    setLoginError('');
    setIsLoading(true);

    const creds = VALID_CREDENTIALS[selectedUserType];

    setTimeout(() => {
      if (loginData.email === creds.email && loginData.password === creds.password) {
        setIsAuthenticated(true);
        setAuthenticatedUser({
          email: loginData.email,
          userType: selectedUserType,
          name: selectedUserType.charAt(0).toUpperCase() + selectedUserType.slice(1)
        });
      } else {
        setLoginError('Invalid email or password. Please try again.');
      }
      setIsLoading(false);
    }, 1000);
  };

  const handleLogout = () => {
    setIsAuthenticated(false);
    setAuthenticatedUser(null);
    setSelectedUserType('');
    setShowLogin(false);
    setLoginData({ email: '', password: '' });
    setLoginError('');
  };

  const handleInputChange = (e) => {
    const { name, value } = e.target;
    setLoginData(prev => ({
      ...prev,
      [name]: value
    }));
    setLoginError('');
  };

  // Show appropriate dashboard if authenticated
  if (isAuthenticated && authenticatedUser) {
    switch (authenticatedUser.userType) {
      case 'student':
        return <StudentDashboard onLogout={handleLogout} />;
      case 'mentor':
        return <MentorDashboard onLogout={handleLogout} />;
      case 'placement-cell':
        return <PlacementDashboard onLogout={handleLogout} />;
      default:
        return null;
    }
  }

  // Login form for selected user type
  if (showLogin && selectedUserType) {
    const userTypeData = userTypes.find(type => type.id === selectedUserType);
    const credentials = VALID_CREDENTIALS[selectedUserType];

    return (
      <div className="min-h-screen bg-gray-50 flex items-center justify-center p-4">
        <div className="max-w-md w-full bg-white border border-gray-200 rounded p-8">
          <button
            onClick={() => {
              setShowLogin(false);
              setSelectedUserType('');
              setLoginError('');
              setLoginData({ email: '', password: '' });
            }}
            className="mb-8 text-sm text-gray-600 hover:text-black"
          >
            ← Back
          </button>

          <h1 className="text-2xl font-medium text-black mb-2">
            Sign In
          </h1>
          <p className="text-sm text-gray-600 mb-8">
            {userTypeData.title}
          </p>

          <form onSubmit={handleLogin}>
            {loginError && (
              <div className="mb-4 p-3 bg-red-50 border border-red-200 rounded">
                <p className="text-sm text-red-700">{loginError}</p>
              </div>
            )}

            <div className="mb-4">
              <label className="block text-sm font-medium text-gray-700 mb-1">
                Email
              </label>
              <input
                type="email"
                name="email"
                value={loginData.email}
                onChange={handleInputChange}
                className="w-full px-3 py-2 border border-gray-300 rounded focus:outline-none focus:border-black"
                placeholder="you@college.edu"
                required
              />
            </div>

            <div className="mb-4">
              <label className="block text-sm font-medium text-gray-700 mb-1">
                Password
              </label>
              <div className="relative">
                <input
                  type={showPassword ? 'text' : 'password'}
                  name="password"
                  value={loginData.password}
                  onChange={handleInputChange}
                  className="w-full px-3 py-2 pr-10 border border-gray-300 rounded focus:outline-none focus:border-black"
                  placeholder="Enter password"
                  required
                />
                <button
                  type="button"
                  onClick={() => setShowPassword(!showPassword)}
                  className="absolute right-3 top-1/2 transform -translate-y-1/2 text-gray-400"
                >
                  {showPassword ? <EyeOff className="h-4 w-4" /> : <Eye className="h-4 w-4" />}
                </button>
              </div>
            </div>

            <div className="mb-6 p-3 bg-gray-50 rounded">
              <p className="text-xs text-gray-600 mb-1">Demo Credentials</p>
              <p className="text-xs text-gray-800 font-mono">{credentials.email} / {credentials.password}</p>
            </div>

            <button
              type="submit"
              disabled={isLoading}
              className="w-full py-2.5 px-4 bg-black text-white font-medium rounded hover:bg-gray-800 disabled:opacity-50"
            >
              {isLoading ? 'Signing in...' : 'Sign In'}
            </button>
          </form>
        </div>
      </div>
    );
  }

  // User type selection (home page)
  return (
    <div className="min-h-screen bg-gradient-to-br from-slate-50 via-blue-50 to-indigo-50">
      {/* Header */}
      <header className="bg-white/80 backdrop-blur-sm border-b border-slate-200 sticky top-0 z-10">
        <div className="max-w-7xl mx-auto px-6 py-4">
          <div className="flex items-center justify-between">
            <div className="flex items-center">
              <div className="p-2 bg-blue-600 rounded-xl mr-3">
                <GraduationCap className="h-6 w-6 text-white" />
              </div>
              <div>
                <h1 className="text-xl font-bold text-slate-900">CampusConnect</h1>
                <p className="text-xs text-slate-600">Career Development Platform</p>
              </div>
            </div>
            <div className="flex items-center space-x-4">
              <span className="text-sm text-slate-600">Trusted by 50,000+ students</span>
            </div>
          </div>
        </div>
      </header>

      {/* Main Content */}
      <main className="max-w-7xl mx-auto px-6 py-12">
        {/* Hero Section */}
        <div className="text-center mb-16">
          <h2 className="text-5xl font-bold text-slate-900 mb-4">
            Welcome to <span className="bg-gradient-to-r from-blue-600 to-purple-600 bg-clip-text text-transparent">CampusConnect</span>
          </h2>
          <p className="text-xl text-slate-600 mb-8">
            Select your role to access your personalized dashboard
          </p>
        </div>

        {/* User Type Cards */}
        <div className="grid grid-cols-1 md:grid-cols-3 gap-8 mb-16">
          {userTypes.map((userType) => {
            const Icon = userType.icon;
            return (
              <div
                key={userType.id}
                onClick={() => {
                  setSelectedUserType(userType.id);
                  setShowLogin(true);
                }}
                className="bg-white rounded-2xl shadow-lg hover:shadow-2xl transform hover:-translate-y-2 transition-all duration-300 cursor-pointer overflow-hidden group"
              >
                <div className={`p-8 bg-gradient-to-r ${userType.color}`}>
                  <div className="flex justify-center mb-4">
                    <div className="p-4 bg-white/20 backdrop-blur-sm rounded-2xl group-hover:scale-110 transition-transform duration-300">
                      <Icon className="h-12 w-12 text-white" />
                    </div>
                  </div>
                  <h3 className="text-2xl font-bold text-white text-center mb-2">
                    {userType.title}
                  </h3>
                  <p className="text-white/90 text-center text-sm">
                    {userType.subtitle}
                  </p>
                </div>
                <div className="p-6">
                  <p className="text-slate-600 text-center mb-4">
                    {userType.description}
                  </p>
                  <button className="w-full py-3 px-6 bg-slate-900 hover:bg-slate-800 text-white font-semibold rounded-xl transition-colors flex items-center justify-center">
                    Get Started
                    <ArrowRight className="h-5 w-5 ml-2" />
                  </button>
                </div>
              </div>
            );
          })}
        </div>

        {/* Features Section */}
        <div className="bg-white rounded-2xl shadow-lg p-8">
          <h3 className="text-2xl font-bold text-slate-900 text-center mb-8">
            Why Choose CampusConnect?
          </h3>
          <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
            <div className="text-center">
              <div className="inline-flex p-4 bg-blue-100 rounded-2xl mb-4">
                <CheckCircle2 className="h-8 w-8 text-blue-600" />
              </div>
              <h4 className="text-lg font-semibold text-slate-900 mb-2">Streamlined Process</h4>
              <p className="text-slate-600">One platform for all your career needs</p>
            </div>
            <div className="text-center">
              <div className="inline-flex p-4 bg-emerald-100 rounded-2xl mb-4">
                <Shield className="h-8 w-8 text-emerald-600" />
              </div>
              <h4 className="text-lg font-semibold text-slate-900 mb-2">Secure & Reliable</h4>
              <p className="text-slate-600">Your data is protected with enterprise-grade security</p>
            </div>
            <div className="text-center">
              <div className="inline-flex p-4 bg-purple-100 rounded-2xl mb-4">
                <GraduationCap className="h-8 w-8 text-purple-600" />
              </div>
              <h4 className="text-lg font-semibold text-slate-900 mb-2">Expert Support</h4>
              <p className="text-slate-600">Get guidance from experienced mentors</p>
            </div>
          </div>
        </div>
      </main>

      {/* Footer */}
      <footer className="bg-white border-t border-slate-200 mt-16">
        <div className="max-w-7xl mx-auto px-6 py-8">
          <div className="text-center text-slate-600 text-sm">
            <p>© 2025 CampusConnect. All rights reserved.</p>
            <p className="mt-2">Need help? Contact support@campusconnect.edu</p>
          </div>
        </div>
      </footer>
    </div>
  );
};

export default ProfessionalLogin;
